style.css:
@-moz-document domain("youtube.com") {
/* ? FONDO */
ytd-app {
    background-color: #FFE4E1 !important;
}

/* ? HEADER */
#masthead {
    background: rgba(191, 126, 129, 0.8) !important;
}

/* ? SIDEBAR */
ytd-guide-renderer {
    background: #BC8F8F !important;
}

/* ? CONTENEDOR MÁS EQUILIBRADO */
ytd-rich-grid-renderer {
    max-width: 1400px !important;
    margin: 0 auto !important;
    padding-left: 20px !important;
    padding-right: 20px !important;
}

/* ? GRID REAL DE 3 COLUMNAS (CORREGIDO) */
ytd-rich-grid-renderer #contents {
    display: grid !important;
    grid-template-columns: repeat(3, minmax(320px, 1fr)) !important;
    gap: 25px !important;
}

/* ? TARJETAS */
ytd-rich-item-renderer {
    background: rgba(255,255,255,0.7) !important;
    border-radius: 16px !important;
    padding: 12px !important;
    box-sizing: border-box !important;
}

/* ✨ HOVER */
ytd-rich-item-renderer:hover {
    transform: translateY(-5px);
}

/* ? TÍTULOS */
a#video-title {
    color: #66021F !important;
    font-size: 15px !important;
    line-height: 1.4 !important;
}

/* ? TEXTO */
#metadata-line {
    color: #5A3A3A !important;
    font-size: 13px !important;
}

/* ? CANALES */
ytd-channel-name a {
    color: #66021F !important;
    font-weight: 600 !important;
}

/* ? CATEGORÍAS */
yt-chip-cloud-chip-renderer {
    background: #FFFFFF !important;
}

yt-chip-cloud-chip-renderer yt-formatted-string {
    color: #66021F !important;
}

/* ? BUSCADOR */
#search {
    background: #FFFFFF !important;
    border-radius: 20px !important;
}

/* ? BOTONES */
ytd-toggle-button-renderer yt-icon,
ytd-button-renderer yt-icon {
    fill: #66021F !important;
    color: #66021F !important;
}

/* ? COMENTARIOS */
#author-text span {
    color: #66021F !important;
}
}
